 65				TokensUsed: &model.TokensUsed{},
 66			}, nil
 67		}
 68	
 69		userMessage := openai.ChatCompletionMessage{
 70			Role:    openai.ChatMessageRoleUser,
 71			Content: userInput,
 72		}
 73	
 74		response, err := chat.agent.PlanAndExecute(ctx, chat.client.svc, chat.messages, userMessage, progressUpdates)
 75		if err != nil {
 76			return nil, trace.Wrap(err)
 77		}
 78	
 79		return response, nil
 80	}
