 91	// AddTokens updates TokensUsed with the tokens used for a single call to an LLM.
 92	func (t *TokensUsed) AddTokens(prompt []openai.ChatCompletionMessage, completion string) error {
 93		for _, message := range prompt {
 94			promptTokens, _, err := t.tokenizer.Encode(message.Content)
 95			if err != nil {
 96				return trace.Wrap(err)
 97			}
 98	
 99			t.Prompt = t.Prompt + perMessage + perRole + len(promptTokens)
100		}
101	
102		completionTokens, _, err := t.tokenizer.Encode(completion)
103		if err != nil {
104			return trace.Wrap(err)
105		}
106	
107		t.Completion = t.Completion + perRequest + len(completionTokens)
108		return err
109	}
